allocation_profiler.source:
#define _GNU_SOURCE
#include <stdatomic.h>
#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>

extern void *__libc_malloc(size_t);
extern void *__libc_calloc(size_t, size_t);
extern void *__libc_realloc(void *, size_t);
extern void __libc_free(void *);
static _Atomic uint64_t malloc_calls, calloc_calls, realloc_calls, free_calls, requested_bytes;

void *malloc(size_t n) {
    atomic_fetch_add_explicit(&malloc_calls, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&requested_bytes, n, memory_order_relaxed);
    return __libc_malloc(n);
}
void *calloc(size_t n, size_t width) {
    atomic_fetch_add_explicit(&calloc_calls, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&requested_bytes, n * width, memory_order_relaxed);
    return __libc_calloc(n, width);
}
void *realloc(void *p, size_t n) {
    atomic_fetch_add_explicit(&realloc_calls, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&requested_bytes, n, memory_order_relaxed);
    return __libc_realloc(p, n);
}
void free(void *p) {
    if (p) atomic_fetch_add_explicit(&free_calls, 1, memory_order_relaxed);
    __libc_free(p);
}
__attribute__((destructor)) static void report_counts(void) {
    const char *path = getenv("CAD_BOOKKEEPING_ALLOC_COUNTS");
    if (!path) return;
    char buf[512];
    int len = snprintf(buf, sizeof(buf),
        "{\"malloc_calls\":%llu,\"calloc_calls\":%llu,\"realloc_calls\":%llu,\"free_calls\":%llu,\"requested_bytes\":%llu}\n",
        (unsigned long long)malloc_calls, (unsigned long long)calloc_calls,
        (unsigned long long)realloc_calls, (unsigned long long)free_calls,
        (unsigned long long)requested_bytes);
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fd >= 0) { (void)write(fd, buf, len); close(fd); }
}

mojo_allocation_profiler.source:
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>

/* The installed runtime ABI is (alignment, size); forward both unchanged.
 * These entry points dispatch to Mojo's TCMallocGlobals, bypassing glibc.
 * Keep these counts separate from the earlier glibc-only diagnostic. */
typedef void *(*alloc_fn)(int64_t, int64_t);
typedef void (*free_fn)(void *);
static alloc_fn real_alloc;
static free_fn real_free;
static _Atomic uint64_t alloc_calls, free_calls, requested_bytes;

__attribute__((constructor)) static void initialize(void) {
    real_alloc = (alloc_fn)dlsym(RTLD_NEXT, "KGEN_CompilerRT_AlignedAlloc");
    real_free = (free_fn)dlsym(RTLD_NEXT, "KGEN_CompilerRT_AlignedFree");
    /* taskset is preloaded too and does not link the Mojo runtime. */
}
void *KGEN_CompilerRT_AlignedAlloc(int64_t alignment, int64_t size) {
    if (!real_alloc) _exit(125);
    atomic_fetch_add_explicit(&alloc_calls, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&requested_bytes, (uint64_t)size, memory_order_relaxed);
    return real_alloc(alignment, size);
}
void KGEN_CompilerRT_AlignedFree(void *p) {
    if (!real_free) _exit(125);
    if (p) atomic_fetch_add_explicit(&free_calls, 1, memory_order_relaxed);
    real_free(p);
}
__attribute__((destructor)) static void report_counts(void) {
    const char *path = getenv("CAD_BOOKKEEPING_ALLOC_COUNTS");
    if (!path || !real_alloc) return;
    char buf[512];
    int len = snprintf(buf, sizeof(buf),
        "{\"mojo_alloc_calls\":%llu,\"mojo_free_calls\":%llu,\"mojo_requested_bytes\":%llu}\n",
        (unsigned long long)alloc_calls, (unsigned long long)free_calls,
        (unsigned long long)requested_bytes);
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fd >= 0) { (void)write(fd, buf, len); close(fd); }
}

mojo_allocation_profiler.smoke_source:
#include <stdint.h>
#include <string.h>
extern void *KGEN_CompilerRT_AlignedAlloc(int64_t alignment, int64_t size);
extern void KGEN_CompilerRT_AlignedFree(void *);
int main(void) {
    void *p = KGEN_CompilerRT_AlignedAlloc(64, 123);
    if (!p || (uintptr_t)p % 64) return 1;
    memset(p, 42, 123);
    KGEN_CompilerRT_AlignedFree(p);
    return 0;
}
